from itertools import combinations

# Fixed edges
fixed_edges = [(2,12), (3,10), (6,9), (3,13), (3,12), (0,13)]

# All possible edges (u, v) with 0 <= u < v < 15
all_possible = [(u, v) for u in range(15) for v in range(u+1, 15)]
fixed_set = set(fixed_edges)
candidate_edges = [e for e in all_possible if e not in fixed_set]

print(f"Number of candidate edges: {len(candidate_edges)}")

# Check for triangles in fixed edges
def has_triangle(edges):
    edge_set = set(edges)
    for u in range(15):
        neighbors_u = [v for v in range(15) if (min(u,v), max(u,v)) in edge_set]
        for i in range(len(neighbors_u)):
            for j in range(i+1, len(neighbors_u)):
                v, w = neighbors_u[i], neighbors_u[j]
                if (min(v,w), max(v,w)) in edge_set:
                    return True
    return False

print(f"Fixed edges have triangles: {has_triangle(fixed_edges)}")

# Let's use a SAT solver approach
from pysat.solvers import Glucose3
from pysat.card import *

# Variables: for each candidate edge, a boolean variable
# We'll use index in candidate_edges as variable index (1-based for SAT)

solver = Glucose3()

# Helper to get variable index for an edge
def edge_var(edge):
    idx = candidate_edges.index(edge)
    return idx + 1

# Constraint 1: No triangles
# For each triple (u, v, w), at most 2 of the 3 edges can be present
for u in range(15):
    for v in range(u+1, 15):
        for w in range(v+1, 15):
            e1 = (u, v)
            e2 = (u, w)
            e3 = (v, w)
            # Check which are candidate edges
            vars_in_triangle = []
            for e in [e1, e2, e3]:
                if e in fixed_set:
                    vars_in_triangle.append(None)  # Fixed present
                elif e in set(candidate_edges):
                    vars_in_triangle.append(edge_var(e))

            # Count fixed edges in this triangle
            fixed_count = sum(1 for x in vars_in_triangle if x is None)
            if fixed_count >= 2:
                # Already have 2 fixed edges, can't add the third
                for x in vars_in_triangle:
                    if x is not None:
                        solver.add_clause([-x])
            elif fixed_count == 1:
                # One fixed edge, can add at most 1 more
                candidate_vars = [x for x in vars_in_triangle if x is not None]
                if len(candidate_vars) == 2:
                    # At most 1 of the 2 can be true
                    solver.add_clause([-candidate_vars[0], -candidate_vars[1]])
            else:
                # No fixed edges, at most 2 of 3 can be true
                candidate_vars = [x for x in vars_in_triangle if x is not None]
                if len(candidate_vars) == 3:
                    # At most 2 of 3: equivalent to not all 3
                    solver.add_clause([-candidate_vars[0], -candidate_vars[1], -candidate_vars[2]])

# Constraint 2: Each vertex has degree between 2 and 5
for v in range(15):
    # Find all edges incident to v
    incident_fixed = []
    incident_candidate = []
    for e in fixed_edges:
        if v in e:
            incident_fixed.append(e)
    for e in candidate_edges:
        if v in e:
            incident_candidate.append(e)

    fixed_degree = len(incident_fixed)
    candidate_vars = [edge_var(e) for e in incident_candidate]

    # Degree >= 2: at least (2 - fixed_degree) candidate edges must be true
    needed = max(0, 2 - fixed_degree)
    if needed > 0:
        if needed <= len(candidate_vars):
            # At least 'needed' of candidate_vars must be true
            # Use CardEnc for at-least constraint
            clauses = CardEnc.atleast(lits=candidate_vars, bound=needed, encoding=1)
            for clause in clauses:
                solver.add_clause(clause)
        else:
            print(f"UNSAT: vertex {v} needs {needed} edges but only has {len(candidate_vars)} candidates")

    # Degree <= 5: at most (5 - fixed_degree) candidate edges can be true
    allowed = 5 - fixed_degree
    if allowed < len(candidate_vars):
        # At most 'allowed' of candidate_vars can be true
        clauses = CardEnc.atmost(lits=candidate_vars, bound=allowed, encoding=1)
        for clause in clauses:
            solver.add_clause(clause)

print("Solving...")
if solver.solve():
    model = solver.get_model()
    selected_edges = fixed_edges[:]
    for i, e in enumerate(candidate_edges):
        if model[i] > 0:  # Variable is true
            selected_edges.append(e)

    # Verify solution
    print(f"Solution found with {len(selected_edges)} edges")

    # Check degrees
    degrees = [0] * 15
    for u, v in selected_edges:
        degrees[u] += 1
        degrees[v] += 1
    print(f"Degrees: {degrees}")
    print(f"Min degree: {min(degrees)}, Max degree: {max(degrees)}")

    # Check girth
    def check_girth(edges):
        edge_set = set(edges)
        # Check for triangles
        for u in range(15):
            neighbors_u = [v for v in range(15) if (min(u,v), max(u,v)) in edge_set]
            for i in range(len(neighbors_u)):
                for j in range(i+1, len(neighbors_u)):
                    v, w = neighbors_u[i], neighbors_u[j]
                    if (min(v,w), max(v,w)) in edge_set:
                        return 3
        # Check for 4-cycles
        for u in range(15):
            neighbors_u = [v for v in range(15) if (min(u,v), max(u,v)) in edge_set]
            for i in range(len(neighbors_u)):
                for j in range(i+1, len(neighbors_u)):
                    v, w = neighbors_u[i], neighbors_u[j]
                    # Check if v and w have a common neighbor other than u
                    neighbors_v = [x for x in range(15) if (min(v,x), max(v,x)) in edge_set and x != u]
                    for x in neighbors_v:
                        if (min(w,x), max(w,x)) in edge_set:
                            return 4
        return 5  # No cycle of length 3 or 4 found

    girth = check_girth(selected_edges)
    print(f"Girth: {girth}")

    # Output edges
    selected_edges.sort()
    print("Edges:", selected_edges)
else:
    print("UNSATISFIABLE")

solver.delete()
